# RFC 9728 protected resource metadata for /mcp (generated by maquina:oauth),
# at the path-suffixed well-known URL a 401 from /mcp points to.
class Oauth::ProtectedResourcesController < ActionController::API
  # GET /.well-known/oauth-protected-resource/mcp
  def show
    expires_in 1.hour, public: true
    render json: {
      resource: "#{request.base_url}/mcp",
      authorization_servers: [request.base_url],
      scopes_supported: AccessToken::SCOPES,
      bearer_methods_supported: ["header"]
    }
  end
end
